<?php ?><!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>PRIMONIZER FOREX AI</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#050a10;color:#eef6ff;font:15px Arial,sans-serif}.wrap{max-width:1500px;margin:auto;padding:16px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px}.brand{font-size:23px;font-weight:900}.brand b{color:#27e0a0}.badge{border:1px solid #29435b;padding:8px 12px;border-radius:20px;color:#9fb4c7}.card{background:#0b1622;border:1px solid #21384e;border-radius:14px;padding:16px;margin-top:14px}.hero{display:grid;grid-template-columns:1.15fr .85fr;gap:12px}.uploadGrid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.muted{color:#91a7bb;line-height:1.55}.slot{border:1px dashed #34536d;border-radius:12px;padding:12px;background:#07111b}.slot input,.slot select{width:100%;margin-top:8px;background:#050d15;color:#fff;border:1px solid #29435b;padding:10px;border-radius:8px}.thumb{display:none;width:100%;height:150px;object-fit:contain;margin-top:8px;background:#02060a}.btn{width:100%;padding:15px;margin-top:14px;border:0;border-radius:10px;background:#27e0a0;color:#03120d;font-weight:900;cursor:pointer}.btn:disabled{opacity:.5}.result{display:none}.charts{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.chartCard{background:#02070d;border:1px solid #29435b;border-radius:12px;overflow:hidden}.chartHead{padding:12px;background:#091521;display:flex;justify-content:space-between;gap:10px}.chartWrap{position:relative;background:#02060a;overflow:auto}.chartImg{width:100%;display:block;cursor:zoom-in}.final{font-size:18px;font-weight:900;white-space:pre-line;line-height:1.55}.error{color:#ff6378;margin-top:10px}.legend{display:flex;flex-wrap:wrap;gap:8px;margin-top:10px}.legend span{padding:5px 8px;border-radius:7px;background:#101e2b;border:1px solid #29435b;font-size:12px}.currentBox{border-left:4px solid #fff;padding:12px;background:#101820;margin-top:8px}.decision{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;margin-top:12px}.decision div{padding:11px;border:1px solid #29435b;background:#07111b;border-radius:9px;text-align:center}.decision b{display:block;color:#27e0a0;font-size:11px;margin-bottom:5px}.story{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.storyStep{border:1px solid #29435b;border-radius:10px;padding:12px;background:#07111b;min-height:95px}.storyStep b{display:block;margin-bottom:7px;color:#27e0a0}.panel{border:1px solid #29435b;border-radius:10px;padding:11px;margin-top:9px}.headline{font-size:22px;font-weight:900;margin:4px 0}.confidence{font-size:12px;color:#9fb4c7}.small{font-size:12px;color:#7890a4}.modal{display:none;position:fixed;z-index:99;inset:0;background:#000e;align-items:center;justify-content:center;padding:15px}.modal.open{display:flex}.modal img{max-width:96vw;max-height:92vh}.close{position:fixed;right:20px;top:10px;font-size:35px;cursor:pointer}@media(max-width:1000px){.hero,.charts,.story{grid-template-columns:1fr}}@media(max-width:700px){.wrap{padding:9px}.uploadGrid,.decision{grid-template-columns:1fr}.top{align-items:flex-start;flex-direction:column}}
</style></head>
<body><div class="wrap">
<div class="top"><div class="brand">PRIMONIZER <b>FOREX AI</b></div><div class="badge">● DEEP MULTI-TIMEFRAME VISUAL TUTOR</div></div>
<div class="hero">
<div class="card"><h1>Upload 1–4 timeframes</h1><p class="muted">Upload the SAME market at different timeframes. Higher timeframes establish context; lower timeframes refine the current-price decision.</p><form id="form"><label>SYMBOL</label><select name="symbol" style="width:100%;background:#050d15;color:white;padding:11px;border:1px solid #29435b;border-radius:8px"><option>XAUUSD</option><option>EURUSD</option><option>GBPUSD</option><option>USDJPY</option><option>BTCUSD</option><option>V75</option><option>OTHER</option></select><div class="uploadGrid" id="slots"></div><button class="btn" id="go">ANALYZE ALL TIMEFRAMES</button><div id="err" class="error"></div></form></div>
<div class="card"><h2>Clean visual decision map</h2><div class="final">STRUCTURE
↓
LIQUIDITY
↓
DISPLACEMENT
↓
BOS / CHoCH
↓
VALID OB / FVG
↓
CURRENT PRICE
↓
ENTRY → CONFIRMATION
↓
INVALIDATION
↓
TP1 → TP2</div><div class="legend"><span>🟢 Bullish / Entry</span><span>🔴 Bearish / Invalidation</span><span>🟡 Liquidity / Targets</span><span>🔵 FVG / Confirmation</span><span>⚪ Structure</span></div><p class="small">Labels stay short, horizontal and close to the price action. Zones and levels carry the meaning instead of scattered text.</p></div></div>
<section id="result" class="result">
<div class="card"><div id="title" class="headline"></div><div id="confidence" class="confidence"></div><div id="final" class="final"></div><div id="current" class="currentBox"></div><p id="reason" class="muted"></p><p id="confluence" class="muted"></p><div class="decision"><div><b>ENTRY</b><span id="dEntry">—</span></div><div><b>CONFIRMATION</b><span id="dConfirm">—</span></div><div><b>INVALIDATION</b><span id="dInvalid">—</span></div><div><b>TP1</b><span id="dTp1">—</span></div><div><b>TP2</b><span id="dTp2">—</span></div></div></div>
<div id="charts" class="charts"></div><div class="card"><h2>Visual Market Story</h2><div id="story" class="story"></div></div></section></div>
<div id="modal" class="modal"><span class="close" id="close">×</span><img id="big"></div>
<script>
const slots=document.getElementById('slots');
for(let i=0;i<4;i++){const s=document.createElement('div');s.className='slot';s.innerHTML='<b>CHART '+(i+1)+'</b><select class="tf"><option>H4</option><option>H1</option><option>M30</option><option>M15</option><option>M5</option><option>M1</option><option>D1</option><option>UNKNOWN</option></select><input class="file" type="file" accept="image/png,image/jpeg,image/webp"><img class="thumb"><small class="small size"></small>';slots.appendChild(s);const f=s.querySelector('.file'),im=s.querySelector('.thumb'),sz=s.querySelector('.size');f.onchange=()=>{if(f.files[0]){im.src=URL.createObjectURL(f.files[0]);im.style.display='block';sz.textContent='Selected: '+(f.files[0].size/1048576).toFixed(2)+' MB'}}}
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function openBig(src){big.src=src;modal.classList.add('open')}close.onclick=()=>modal.classList.remove('open');modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};
function compress(file){return new Promise((resolve,reject)=>{const im=new Image(),u=URL.createObjectURL(file);im.onload=()=>{let w=im.naturalWidth,h=im.naturalHeight,m=Math.max(w,h);if(m>1800){w=Math.round(w*1800/m);h=Math.round(h*1800/m)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(im,0,0,w,h);c.toBlob(b=>{URL.revokeObjectURL(u);b?resolve(new File([b],'chart.jpg',{type:'image/jpeg'})):reject(new Error('Could not prepare image'))},'image/jpeg',.8)};im.onerror=()=>reject(new Error('Could not read image'));im.src=u})}
function col(t){t=String(t||'').toUpperCase();if(['OB_BULL','ENTRY','TARGET1','TARGET2','HL'].includes(t))return '#27e0a0';if(['OB_BEAR','INVALIDATION','LH','LL'].includes(t))return '#ff6378';if(['FVG','CONFIRMATION','BOS','CHOCH','DISPLACEMENT'].includes(t))return '#55a9ff';if(['LIQUIDITY','SWEEP','TARGET','SUPPORT','RESISTANCE','PREMIUM','DISCOUNT'].includes(t))return '#ffd166';return '#f4f7fb'}
function xy(o,W,H){return [Math.max(0,Math.min(W,(+o.x||0)*W)),Math.max(0,Math.min(H,(+o.y||0)*H))]}
function drawLabel(ctx,text,x,y,color,align='center',size=13){ctx.save();ctx.font='900 '+size+'px Arial';const w=ctx.measureText(text).width+14,h=size+12;let bx=x-(align==='center'?w/2:align==='right'?w:0);let by=y-h/2;ctx.fillStyle='rgba(2,6,10,.88)';ctx.fillRect(bx,by,w,h);ctx.strokeStyle=color;ctx.lineWidth=1.5;ctx.strokeRect(bx,by,w,h);ctx.fillStyle='#fff';ctx.textBaseline='middle';ctx.textAlign='left';ctx.fillText(text,bx+7,y);ctx.restore()}
function line(ctx,x1,y1,x2,y2,color,width=2,dash=[]){ctx.save();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.setLineDash(dash);ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();ctx.restore()}
function zone(ctx,x1,y1,x2,y2,color,label){const l=Math.min(x1,x2),t=Math.min(y1,y2),w=Math.max(5,Math.abs(x2-x1)),h=Math.max(5,Math.abs(y2-y1));ctx.save();ctx.globalAlpha=.12;ctx.fillStyle=color;ctx.fillRect(l,t,w,h);ctx.globalAlpha=1;ctx.strokeStyle=color;ctx.lineWidth=2.5;ctx.setLineDash([7,5]);ctx.strokeRect(l,t,w,h);ctx.restore();if(label)drawLabel(ctx,label,l+8,t+16,color,'left',12)}
function annotate(src,chart,overall,finalDiagram){return new Promise(resolve=>{const im=new Image();im.onload=()=>{const c=document.createElement('canvas');const W=Math.min(1800,im.naturalWidth),H=Math.round(im.naturalHeight*(W/im.naturalWidth));c.width=W;c.height=H;const ctx=c.getContext('2d');ctx.drawImage(im,0,0,W,H);
 const anns=Array.isArray(chart?.annotations)?chart.annotations:[], used=[];
 const byType={};anns.forEach(a=>(byType[a.type]=byType[a.type]||[]).push(a));
 // Zones first: OB/FVG are visual regions, not floating words.
 anns.filter(a=>['OB_BULL','OB_BEAR','FVG'].includes(String(a.type).toUpperCase())&&a.x2!=null&&a.y2!=null).forEach(a=>{const p=xy(a,W,H),q=xy({x:a.x2,y:a.y2},W,H);zone(ctx,p[0],p[1],q[0],q[1],col(a.type),a.type==='FVG'?'FVG':(a.type==='OB_BULL'?'BULLISH OB':'BEARISH OB'));});
 // Structure levels are horizontal and compact.
 anns.filter(a=>['SUPPORT','RESISTANCE','LIQUIDITY','PREMIUM','DISCOUNT'].includes(String(a.type).toUpperCase())).forEach(a=>{const p=xy(a,W,H),q=a.x2!=null?xy({x:a.x2,y:a.y2??a.y},W,H):[W,p[1]];line(ctx,p[0],p[1],q[0],q[1],col(a.type),2,[7,5]);drawLabel(ctx,a.label||a.type,p[0]+8,p[1]-12,col(a.type),'left',11)});
 // Trend lines are actual lines, not labels scattered around the chart.
 anns.filter(a=>['TRENDLINE','TREND_UP','TREND_DOWN'].includes(String(a.type).toUpperCase())&&a.x2!=null).forEach(a=>{const p=xy(a,W,H),q=xy({x:a.x2,y:a.y2},W,H);line(ctx,p[0],p[1],q[0],q[1],col(a.type),3,[12,7]);});
 // Main annotations: one short label anchored at its exact point.
 anns.filter(a=>!['OB_BULL','OB_BEAR','FVG','SUPPORT','RESISTANCE','LIQUIDITY','PREMIUM','DISCOUNT','TRENDLINE','TREND_UP','TREND_DOWN'].includes(String(a.type).toUpperCase())).forEach(a=>{const p=xy(a,W,H),t=String(a.type||'').toUpperCase();let label=a.label||t;if(t==='CURRENT')label='CURRENT PRICE';if(t==='TARGET1')label='TP1';if(t==='TARGET2')label='TP2';if(t==='INVALIDATION')label='INVALIDATION';if(t==='CONFIRMATION')label='CONFIRM';if(t==='DISPLACEMENT')label='DISPLACEMENT';drawLabel(ctx,label,p[0],p[1],col(t),'center',t==='CURRENT'?13:11);used.push({x:p[0],y:p[1]})});
 // Explicit decision path is drawn as a clean directional path, never as floating words.
 const path=Array.isArray(chart?.path)?chart.path:[];if(path.length>1){for(let i=0;i<path.length-1;i++){const p=xy(path[i],W,H),q=xy(path[i+1],W,H);line(ctx,p[0],p[1],q[0],q[1],col(path[i].label),2.5,[9,6]);const ang=Math.atan2(q[1]-p[1],q[0]-p[0]);ctx.save();ctx.fillStyle=col(path[i].label);ctx.translate(q[0],q[1]);ctx.rotate(ang);ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(-10,-5);ctx.lineTo(-10,5);ctx.closePath();ctx.fill();ctx.restore()}}
 // Final diagram is shown only as a compact right-side decision rail when coordinates exist.
 if(finalDiagram&&Array.isArray(finalDiagram.steps)&&finalDiagram.steps.length){const steps=finalDiagram.steps.filter(s=>s&&s.x!=null&&s.y!=null);for(let i=0;i<steps.length-1;i++){const p=xy(steps[i],W,H),q=xy(steps[i+1],W,H);line(ctx,p[0],p[1],q[0],q[1],'#ffffff',1.6,[5,6])}}
 resolve(c.toDataURL('image/jpeg',.88))};im.src=src})}
function cardHtml(chart,src,annotated){const d=chart||{};const ob=d.valid_order_block||{};const e=d.entry||{};const concepts=Array.isArray(d.concepts)?d.concepts:[];const tut=Array.isArray(d.tutorial)?d.tutorial:[];return '<div class="chartCard"><div class="chartHead"><b>'+esc(d.timeframe||('CHART '+d.index))+'</b><span>'+esc(d.role||'')+' · '+esc(d.direction||'')+'</span></div><div class="chartWrap"><img class="chartImg" src="'+annotated+'" onclick="openBig(this.src)"></div><div class="panel"><b>Current price</b><p class="muted">'+esc(d.current_state||d.current_price_note||'—')+'</p></div><div class="panel"><b>Order Block</b><p class="muted">'+esc(ob.status||'NONE')+' — '+esc(ob.why||'No explanation returned.')+'</p></div><div class="panel"><b>Entry</b><p class="muted">'+esc(e.state||'NONE')+' — '+esc(e.zone||'—')+'</p><p class="small">Confirmation: '+esc(e.confirmation||'—')+' · Invalidation: '+esc(e.invalidation||'—')+'</p></div>'+concepts.map(x=>'<div class="panel"><b>'+esc(x.name||'Concept')+'</b><p class="muted"><strong>What:</strong> '+esc(x.what||'—')+'<br><strong>Why:</strong> '+esc(x.why||'—')+'</p></div>').join('')+(tut.length?'<div class="panel"><b>Visual explanation</b>'+tut.map(x=>'<p class="small"><strong>'+esc(x.title||'')+':</strong> '+esc(x.text||'')+'</p>').join('')+'</div>':'')+'</div>'}
form.onsubmit=async ev=>{ev.preventDefault();err.textContent='';go.disabled=true;go.textContent='ANALYZING...';try{const fd=new FormData(form),files=[...document.querySelectorAll('.file')],tfs=[...document.querySelectorAll('.tf')];let n=0;for(let i=0;i<files.length;i++){if(files[i].files[0]){const f=await compress(files[i].files[0]);fd.append('charts[]',f,'chart-'+(i+1)+'.jpg');fd.append('timeframes[]',tfs[i].value);n++}}if(!n)throw new Error('Upload at least one chart screenshot.');const r=await fetch('analyze.php',{method:'POST',body:fd});const data=await r.json();if(!r.ok||data.error)throw new Error(data.error||'Analysis failed.');render(data)}catch(e){err.textContent=e.message||'Analysis failed.'}finally{go.disabled=false;go.textContent='ANALYZE ALL TIMEFRAMES'}};
async function render(data){const a=data.analysis||{},o=a.overall||{};result.style.display='block';title.textContent=o.headline||'PRIMONIZER ANALYSIS';confidence.textContent='State: '+(o.trade_state||'WAIT')+' · Confidence: '+(o.confidence??'—');final.textContent='CURRENT → '+(o.next_move||'WAIT')+'\n'+(o.entry_plan||'ENTRY: —')+'\nCONFIRM → '+(o.confirmation||'—')+'\nINVALIDATION → '+(o.invalidation||'—')+'\nTP1 → '+(o.targets?.tp1||'—')+'\nTP2 → '+(o.targets?.tp2||'—');current.textContent='CURRENT PRICE: '+(o.current_price_context||'—');reason.textContent=o.reason||'';confluence.textContent=Array.isArray(a.confluence)?'CONFLUENCE: '+a.confluence.join(' · '):'';dEntry.textContent=o.entry_plan||'—';dConfirm.textContent=o.confirmation||'—';dInvalid.textContent=o.invalidation||'—';dTp1.textContent=o.targets?.tp1||'—';dTp2.textContent=o.targets?.tp2||'—';charts.innerHTML='';const originals=[...document.querySelectorAll('.file')].map(f=>f.files[0]).filter(Boolean);const cs=Array.isArray(a.charts)?a.charts:[];for(let i=0;i<cs.length;i++){if(!originals[i])continue;const src=URL.createObjectURL(originals[i]);const img=await annotate(src,cs[i],o,a.final_diagram||{});charts.insertAdjacentHTML('beforeend',cardHtml(cs[i],src,img))}story.innerHTML=(Array.isArray(o.market_story)?o.market_story:[]).map((x,i)=>'<div class="storyStep"><b>STEP '+(i+1)+'</b>'+esc(x)+'</div>').join('')}
</script></body></html>
